<template>
  <div class="device_computing">
    <!-- 搜索区域 -->
    <div class="serch">
      <el-button type="primary" size="small" icon="el-icon-plus" @click="showAddDialog">新增算力设备</el-button>
    </div>

    <!-- 表格区域 -->
    <div class="table">
      <div class="jia_table">
        <el-table :data="tableData" style="width: 100%" :header-cell-style="{ background: '#f9fbff', height: '48.5px', fontSize: '14px' }" height="95%">
          <el-table-column prop="id" label="设备ID"></el-table-column>
          <el-table-column prop="computing_name" label="设备名称"></el-table-column>
          <el-table-column prop="computing_code" label="算力设备编码"></el-table-column>
          <el-table-column prop="computing_ip" label="IP 地址"></el-table-column>
          <el-table-column prop="computing_user" label="账号"></el-table-column>
          <el-table-column prop="created_at" label="创建时间" :show-overflow-tooltip="true">
            <template slot-scope="scope">
              {{ formatGmtToDate(scope.row.created_at) }}
            </template>
          </el-table-column>
          <el-table-column prop="computing_status" label="状态">
            <template slot-scope="scope">
              <span v-if="scope.row.computing_status == '1'" style="color: rgb(48, 245, 48);">在线</span>
              <span v-if="scope.row.computing_status == '2'" style="color: red;">离线</span>
              <span v-if="scope.row.computing_status == '3'" style="color: red;">账密错误</span>
            </template>
          </el-table-column>
          <!-- <el-table-column prop="updated_at" label="更新时间">
            <template slot-scope="scope">
              {{ formatGmtToDate(scope.row.updated_at) }}
            </template>
          </el-table-column> -->
          <!-- 操作栏 -->
          <el-table-column label="操作" width="200">
            <template slot-scope="scope">
              <el-button size="mini" type="text" icon="el-icon-edit" @click="handleEdit(scope.$index, scope.row)">编辑</el-button>
              <el-button size="mini" type="text" icon="el-icon-delete" @click="handleDelete(scope.$index, scope.row)">删除</el-button>
            </template>
          </el-table-column>
        </el-table>
        <!-- 如果没有数据，显示空状态 -->
        <el-empty v-if="tableData.length === 0" image="/static/img/home/placeholder_kong.png" :image-size="307" description="暂时没有数据~"></el-empty>
      </div>

      <!-- 分页控件 -->
      <div class="page">
        <el-pagination @size-change="handleSizeChange" @current-change="handleCurrentChange" :current-page="queryParams.page" :page-size="queryParams.per_page" :total="pagination.total_items" layout="total, sizes, prev, pager, next, jumper" :page-sizes="[10, 15, 20, 50]"></el-pagination>
      </div>
    </div>

    <!-- 新增/编辑对话框 -->
    <el-dialog :title="dialogTitle" :visible.sync="dialogVisible" width="30%">
      <el-form :model="form" ref="computingForm" :rules="rules" label-width="120px">
        <!-- <el-form-item label="算力设备ID" prop="id">
          <el-input v-model="form.id" placeholder="请输入算力设备ID" disabled></el-input>
        </el-form-item> -->
        <el-form-item label="算力设备名称" prop="computing_name">
          <el-input v-model="form.computing_name" placeholder="请输入算力设备名称"></el-input>
        </el-form-item>
        <!-- <el-form-item label="算力设备编码" prop="computing_code">
          <el-input v-model="form.computing_code" placeholder="请输入算力设备编码"></el-input>
        </el-form-item> -->
        <el-form-item label="IP 地址" prop="computing_ip">
          <el-input v-model="form.computing_ip" placeholder="请输入算力设备IP"></el-input>
        </el-form-item>
        <el-form-item label="账号" prop="computing_user">
          <el-input v-model="form.computing_user" placeholder="请输入算力设备账号"></el-input>
        </el-form-item>
        <el-form-item label="密码" prop="computing_password">
          <el-input v-model="form.computing_password" type="password" show-password placeholder="请输入算力设备密码"></el-input>
        </el-form-item>
        <!-- <el-form-item label="创建时间" prop="created_at">
          <el-input v-model="form.created_at" placeholder="请选择创建时间" disabled></el-input>
        </el-form-item>
        <el-form-item label="更新时间" prop="updated_at">
          <el-input v-model="form.updated_at" placeholder="请选择更新时间" disabled></el-input>
        </el-form-item> -->
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button @click="dialogVisible = false">取 消</el-button>
        <el-button type="primary" @click="submitForm('computingForm')">确 定</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
import { getcomputing, addcompputing, deletecomputing, updatecomputing } from '@/api/sfgl';

export default {
  data() {
    return {
      tableData: [], // 表格数据
      pagination: {}, // 分页信息
      queryParams: { // 查询参数
        page: 1,
        per_page: 15
      },
      dialogVisible: false, // 控制对话框显示
      dialogTitle: '', // 对话框标题
      form: {
        id: null,
        computing_name: '',
        computing_ip: '',
        computing_code: '',
        computing_user: '',
        computing_password: '',
      },
      rules: {
        computing_name: [
          { required: true, message: '请输入设备名称', trigger: ['blur', 'change'] }
        ],
        computing_ip: [
          { required: true, message: '请输入IP地址', trigger: ['blur', 'change'] },
          { pattern: /^(\d{1,2}|1\d\d|2[0-4]\d|25[0-5])\.(\d{1,2}|1\d\d|2[0-4]\d|25[0-5])\.(\d{1,2}|1\d\d|2[0-4]\d|25[0-5])\.(\d{1,2}|1\d\d|2[0-4]\d|25[0-5])$/, message: '请输入有效的IP地址', trigger: ['blur', 'change'] }
        ],
        computing_code: [
          { required: true, message: '请输入设备编码', trigger: ['blur', 'change'] }
        ],
        computing_user: [
        { required: true, message: '请输入账号', trigger: ['blur', 'change'] }
        ],
        computing_password: [
        { required: true, message: '请输入密码', trigger: ['blur', 'change'] }
        ],
      },
      editIndex: -1,// 编辑时的索引
      config: {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      }
    };
  },
  methods: {
    fetchData() {
      this.$http.get(getcomputing, {
        params: this.queryParams
      }).then(response => {
        const resData = response.data.data;
        this.tableData = resData.data;
        this.pagination = resData.pagination;
      }).catch(error => {
        console.error('获取数据失败:', error);
      });
    },
    handleSizeChange(val) {
      this.queryParams.per_page = val;
      this.fetchData();
    },
    handleCurrentChange(val) {
      this.queryParams.page = val;
      this.fetchData();
    },
    showAddDialog() {
      this.dialogTitle = '新增算力设备';
      this.form = { id: null, computing_name: '', computing_ip: '' }; // 清空表单
      this.dialogVisible = true;
    },
    handleEdit(index, row) {
      this.editIndex = index;
      this.dialogTitle = '编辑算力设备';
      this.form = { ...row }; // 复制当前行的数据到表单
      this.dialogVisible = true;
    },
    handleDelete(index, row) {
      this.$confirm('此操作将永久删除该算力设备, 是否继续?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        let msg = {
          id: row.id
        }
        let formData = new FormData();
        // 遍历 msg 对象，并将键值对添加到 formData 中
        Object.keys(msg).forEach(key => {
          formData.append(key, msg[key]);
        });
        this.$http.post(deletecomputing, formData, this.config)
          .then(response => {
            if (response.data.code === 200) {
              this.$message({
                type: 'success',
                message: response.data.msg
              });
              this.fetchData(); // 刷新数据
            } else {
              this.$message.error('删除失败');
            }
          })
          .catch(rek => {
            console.log(rek)
          })
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消删除'
        });
      });
    },
    submitForm(formName) {
      this.$refs[formName].validate((valid) => {
        if (valid) {
          let formData = new FormData();

          // 遍历 msg 对象，并将键值对添加到 formData 中
          Object.keys(this.form).forEach(key => {
            formData.append(key, this.form[key]);
          });
          if (this.dialogTitle == '新增算力设备') {
            // 新增操作
            this.$http.post(addcompputing, formData, this.config)
              .then(response => {
                if (response.data.code === 200) {
                  this.$message({
                    type: 'success',
                    message: response.data.msg
                  });
                  this.dialogVisible = false
                  this.fetchData(); // 刷新数据
                } else {
                  this.$message.error(response.data.msg);
                }
              })
              .catch(rek => {
                console.log(rek)
              })
          } else {
            // 修改操作
            this.$http.post(updatecomputing, formData, this.config)
              .then(response => {
                if (response.data.code === 200) {
                  this.$message({
                    type: 'success',
                    message: response.data.msg
                  });
                  this.fetchData(); // 刷新数据
                  this.dialogVisible = false
                } else {
                  this.$message.error(response.data.msg);
                }
              })
              .catch(rek => {
                console.log(rek)
              })

          }
        } else {
          console.log('表单验证失败!');
          return false;
        }
      });
    },
    formatGmtToDate(gmtString) {
      const date = new Date(gmtString);

      // 获取年份、月份（需要加1）、日期
      const year = date.getUTCFullYear();
      let month = date.getUTCMonth() + 1;
      let day = date.getUTCDate();

      // 获取小时、分钟和秒（使用 UTC 方法获取 GMT 时间）
      let hours = date.getUTCHours();
      let minutes = date.getUTCMinutes();
      let seconds = date.getUTCSeconds();

      // 使用 padStart 确保月份、日期、小时、分钟和秒都是两位数
      month = String(month).padStart(2, '0');
      day = String(day).padStart(2, '0');
      hours = String(hours).padStart(2, '0');
      minutes = String(minutes).padStart(2, '0');
      seconds = String(seconds).padStart(2, '0');

      // 返回格式化后的 GMT 时间字符串
      const gmtTime = `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;

      // 同样方法获取本地时间
      // let localHours = String(date.getHours()).padStart(2, '0');
      // let localMinutes = String(date.getMinutes()).padStart(2, '0');
      // let localSeconds = String(date.getSeconds()).padStart(2, '0');
      // const localTime = `${year}-${month}-${day} ${localHours}:${localMinutes}:${localSeconds}`;

      return gmtTime;
    },
  },
  created() {
    this.fetchData();
  }
};
</script>
  
  <style lang="scss" scoped>
.device_computing {
  width: 100%;
  height: 100%;
  background-color: #ffffff;
  border-radius: 6px;
  .serch {
    height: 70px;
    // padding-top: 16px;
    // padding-bottom: 16px;
    padding: 16px 18px;
    box-sizing: border-box;
    position: relative;
    .demo-ruleForm {
      height: 100%;
      display: flex;
      justify-content: left;
      align-items: flex-start;
      flex-wrap: wrap;
    }
  }
  .table {
    height: 87%;
    position: relative;
    .jia_table {
      height: 100%;
      .el-table {
        height: 100%;
        background-image: url("../../../img/home/placeholder_bottom.png");
        background-position: bottom;
        background-size: 100% 60%;
        background-repeat: no-repeat;
      }
      ::v-deep .el-table--border .el-table__cell,
      .el-table__body-wrapper .el-table--border.is-scrolling-left ~ .el-table__fixed {
        border-right: none;
      }
      ::v-deep .el-table__empty-block {
        // display: none !important;
        .el-table__empty-text {
          color: transparent;
        }
      }
      ::v-deep .el-empty {
        width: 307px;
        height: 353px;
        position: absolute;
        top: 50%;
        left: 50%;
        margin-left: -153px;
        margin-top: -176px;
        .el-empty__image img {
          vertical-align: top;
          height: 147%;
          width: 100%;
        }
        .el-empty__description {
          margin-top: 20px;
          margin-right: 70px;
        }
      }
    }
    .page {
      width: 100%;
      height: 33px;
      // background-color: pink;
      text-align: right;
      position: absolute;
      right: 0;
      bottom: -24px;
    }
  }
  ::v-deep .roleForm {
    .el-form-item {
      margin-bottom: 15px !important;
    }
    .el-form-item__label {
      padding-bottom: 0;
    }
    .el-select,
    .el-input {
      // width: 177px;
      .el-input__inner {
        // width: 177px;
        // height: 33px;
        background: #f7f6fb;
        border-radius: 4px;
        border: 1px solid #dcdfe6;
        box-sizing: border-box;
      }
      .el-input__suffix-inner {
        border-left: 1px solid #dcdfe6;
      }
    }
  }
}
</style>